from common import *
from verify import CP
src('igeeks-v3'); dom('cpp')
INC='#include <iostream>\n#include <string>\n#include <vector>\n#include <map>\n#include <memory>\nusing namespace std;\n'
def P(body,pre=''): return INC+pre+'\nint main() {\n'+body+'\n}'
topic('Operators & Control')
M('b','k',"Which header declares std::cout?","<iostream>","<stdio.h>","<cout>","<io>","iostream declares the standard stream objects cin, cout and cerr.")
M('b','k',"Which operator is used with cout to send output?","<<",">>","<-","::","cout << value inserts the value into the output stream. >> is used with cin.")
CP('b','o',"What does this program print?",P('    cout << 7 / 2 << endl;'),"3","3.5","4","2","Both operands are int, so the division is an integer division.")
CP('b','o',"What does this program print?",P('    int a = 7;\n    cout << a / 2.0 << endl;'),"3.5","3","4","3.50","Dividing by the double 2.0 makes the whole expression a double.")
CP('b','o',"What does this program print?",P('    cout << (5 > 3) << endl;'),"1","true","5","0","A bool prints as 1 or 0 unless boolalpha is used.")
CP('b','o',"What does this program print?",P('    cout << boolalpha << (5 > 3) << endl;'),"true","1","yes","5 > 3","boolalpha makes bool values print as the words true and false.")
topic('Memory & Smart Pointers')
CP('b','o',"What does this program print?",P('    int x = 5;\n    int &r = x;\n    r = 10;\n    cout << x << endl;'),"10","5","15","Error","A reference is another name for x, so assigning to r changes x.")
M('b','k',"Which keyword allocates an object on the heap?","new","malloc only","alloc","create","new allocates memory and runs the constructor. It must be paired with delete, or smart pointers should be used.")
M('b','k',"What is the default access level of members in a class?","private","public","protected","It depends on the compiler","In a class members are private by default. In a struct they are public.")
M('b','k',"What does :: mean in std::string?","Scope resolution: string is looked up inside namespace std","Division","Pointer access","Comparison","The scope resolution operator selects a name from a namespace or class.")
topic('OOP & Classes')
M('b','k',"What is the name of a class constructor?","The same as the class name","init","constructor","new","A constructor has the class name and no return type.")
topic('STL & Templates')
CP('b','o',"What does this program print?",P('    string s = "hi";\n    cout << s.size() << endl;'),"2","3","hi","1","size() returns the number of characters, excluding any terminator.")
CP('b','o',"What does this program print?",P('    vector<int> v = {1, 2, 3};\n    cout << v.size() << endl;'),"3","2","4","0","The initializer list creates a vector with three elements.")
M('b','k',"What does for (auto x : v) do?","Visits each element of v in turn (a range-based for loop)","Declares a variable named auto","Copies v into x","Loops forever","Range-based for loops iterate over containers and arrays. Use auto& to avoid copying.")
M('b','k',"Which keyword makes a variable read-only after initialisation?","const","static","final","readonly","const prevents modification through that name.")
topic('OOP & Classes')
CP('i','o',"What does this program print?",P('    Base *p = new Derived();\n    p->f();\n    delete p;','struct Base { virtual void f() { cout << "Base\\n"; } virtual ~Base() {} };\nstruct Derived : Base { void f() override { cout << "Derived\\n"; } };'),"Derived","Base","Base Derived","Nothing","f is virtual, so the call is dispatched on the real object type at run time.")
CP('i','o',"What does this program print?",P('    Base *p = new Derived();\n    p->f();\n    delete p;','struct Base { void f() { cout << "Base\\n"; } virtual ~Base() {} };\nstruct Derived : Base { void f() { cout << "Derived\\n"; } };'),"Base","Derived","Compile error","Both","Without virtual, the function is chosen from the static type of the pointer, which is Base.")
topic('STL & Templates')
CP('i','o',"What does this program print?",P('    map<string, int> m;\n    m["a"];\n    cout << m.size() << endl;'),"1","0","Error","undefined","operator[] inserts a default-constructed value when the key is missing, so the map now has one entry.")
CP('i','o',"What does this program print?",P('    f(x);\n    cout << x << endl;','void f(int v) { v = 5; }\nint x = 1;'),"1","5","0","Error","The parameter is a copy. Use int& to modify the caller's variable.")
CP('i','o',"What does this program print?",P('    cout << 5 / 2 << " " << 5 / 2.0 << endl;'),"2 2.5","2.5 2.5","2 2","3 2.5","The first division has two ints and truncates. The second involves a double.")
topic('Memory & Smart Pointers')
M('i','k',"What does RAII mean?","Resources are acquired in a constructor and released in the destructor","Run all initialisers immediately","Reference arguments are always initialised","Random access iterator interface","Tying a resource to an object's lifetime guarantees cleanup even when exceptions occur.")
topic('OOP & Classes')
M('i','k',"What does marking a member function const promise?","It does not modify the object's visible state","The function runs at compile time","The function cannot be overridden","The function returns a constant","A const member function can be called on const objects.")
topic('Memory & Smart Pointers')
CP('a','o',"What does this program print?",P('    {\n        A a;\n        B b;\n    }','struct A { A() { cout << "a"; } ~A() { cout << "A"; } };\nstruct B { B() { cout << "b"; } ~B() { cout << "B"; } };'),"abBA","abAB","aAbB","bBaA","Objects are constructed in declaration order (a, b) and destroyed in reverse order (B, A).")
CP('a','o',"What does this program print?",P('    Base b = Derived();\n    b.f();','struct Base { virtual void f() { cout << "Base\\n"; } };\nstruct Derived : Base { void f() override { cout << "Derived\\n"; } };'),"Base","Derived","Compile error","Nothing","Assigning a Derived to a Base object slices off the derived part, so the object really is a Base.")
CP('a','o',"What does this program print?",P('    int x = 1;\n    auto f = [x]() mutable { return ++x; };\n    f();\n    cout << f() << x << endl;'),"31","21","11","33","The lambda keeps its own copy of x, which starts at 1. Each of the two calls increments that copy (to 2, then 3). The outer x stays 1, so the output is 3 followed by 1.")
M('a','k',"What does std::move do?","Casts its argument to an rvalue reference so a move can happen; it moves nothing itself","Moves memory to a new address","Copies an object faster","Deletes the original object","The actual move is done by the move constructor or move assignment that receives the rvalue.")
M('a','k',"Why can a std::unique_ptr not be copied?","Because it models sole ownership. Ownership can only be transferred with std::move","Because copying is slow","Because it holds an array","Because it is const","Two unique_ptrs owning the same object would delete it twice.")
M('a','k',"Two objects hold shared_ptr references to each other. What is the problem?","A reference cycle: the counts never reach zero so they are never destroyed","They are destroyed twice","The program does not compile","A deadlock occurs","Break the cycle by making one of the links a weak_ptr.")
M('a','k',"Why should the destructor of a polymorphic base class be virtual?","Deleting a derived object through a base pointer would otherwise skip the derived destructor","Virtual destructors run faster","It is required for all classes","So the class can be copied","Without virtual, deleting through Base* is undefined behaviour.")
M('a','k',"After calling push_back on a std::vector, what may happen to existing iterators?","They may be invalidated if the vector reallocates","They always stay valid","They point to the first element","They are automatically updated","Reallocation moves the elements, so iterators, pointers and references to them become invalid.")
M('a','k',"When must you use dynamic_cast rather than static_cast between base and derived pointers?","When you need a checked downcast at run time and the base is polymorphic","When casting between int and double","When removing const","Never, they are identical","dynamic_cast returns nullptr (for pointers) if the object is not really of the target type. static_cast does no check.")
M('a','k',"What does the Rule of Five say?","If a class needs a custom destructor, copy or move operations, it probably needs all five special functions defined","A class must have at most five members","Use at most five template parameters","A function should have five arguments at most","Destructor, copy constructor, copy assignment, move constructor and move assignment usually belong together.")
M('a','k',"What does constexpr on a function mean?","It can be evaluated at compile time when called with constant arguments","It is always inlined","It cannot be called at run time","It has no side effects only by convention","constexpr functions can be used in constant expressions, such as array sizes, and also work at run time.")
M('a','k',"A template is declared as template<class T> T add(T a, T b). What happens with add(1, 2.5)?","Deduction fails because T would be both int and double","It returns 3.5","It returns 3","It is converted to string","The deduced types conflict, so the call does not compile. add<double>(1, 2.5) works.")
